1	// Package chainledger graph structure rules shared by every graph reader.
2	//
3	// Both on-disk graph files (UnmarshalGraphFile) and the graph embedded in a
4	// snapshot (ParseSnapshot) describe the same thing: a set of dataset names and
5	// each dataset's direct upstreams. The rules below are the single authority for
6	// turning that description into the validated, normalized adjacency both
7	// readers build on, so the two file formats can never disagree about whether
8	// one graph is legal or about which lineage relations it expresses:
9	//
10	//   - an empty dataset name is rejected;
11	//   - a dataset declared more than once is rejected;
12	//   - an upstream that is not itself a declared dataset is rejected, with the
13	//     referrer and the referenced name both in the error;
14	//   - a direct self-dependency or any indirect dependency cycle is rejected,
15	//     with the datasets on the cycle named;
16	//   - names are case-sensitive and surrounding whitespace is kept verbatim;
17	//   - record order and upstream order are irrelevant, duplicate upstreams count
18	//     as one relationship, and an empty upstream list marks a root, so an
19	//     empty graph stays legal;
20	//   - a known field declared twice within the same object (datasets in the
21	//     graph object, name or upstreams in a dataset record) is rejected,
22	//     however the two declarations are spelled; that JSON-level scan is
23	//     shared by every document reader and lives in duplicate_fields.go.
24	//
25	// The snapshot-only envelope rules (required fields, format version, content
26	// identifier, and duplicates of the snapshot's own fields) live in
27	// snapshot.go; this file is only the common graph structure.
28	package chainledger
29	
30	import (
31		"fmt"
32		"sort"
33		"strings"
34	)
35	
36	// adjacency maps a dataset name to its sorted, duplicate-free parent names.
37	type adjacency map[string][]string
38	
39	// normalizeDatasets builds the normalized parent adjacency from parsed dataset
40	// records. It rejects empty dataset names and datasets declared more than
41	// once; every surviving upstream list is sorted and deduplicated. It does not
42	// check that upstreams resolve to a declared dataset; use
43	// validateAdjacencyReferences for that.
44	func normalizeDatasets(datasets []GraphDataset) (adjacency, error) {
45		adj := make(adjacency, len(datasets))
46		for _, ds := range datasets {
47			if ds.Name == "" {
48				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
49			}
50			if _, exists := adj[ds.Name]; exists {
51				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
52			}
53			adj[ds.Name] = uniqueSorted(ds.Upstreams)
54		}
55		return adj, nil
56	}
57	
58	// validateAdjacencyReferences rejects an edge whose upstream is not a declared
59	// dataset. Referrers are visited in sorted order with their parents sorted, so
60	// the first reported (referrer, upstream) pair is stable regardless of map
61	// iteration or record order.
62	func validateAdjacencyReferences(adj adjacency) error {
63		names := make([]string, 0, len(adj))
64		for name := range adj {
65			names = append(names, name)
66		}
67		sort.Strings(names)
68		for _, name := range names {
69			for _, parent := range adj[name] {
70				if _, ok := adj[parent]; !ok {
71					return fmt.Errorf("%w: dataset %q references upstream %q which is not registered", ErrNotFound, name, parent)
72				}
73			}
74		}
75		return nil
76	}
77	
78	// validateGraphStructureFromFile runs every graph-structure rule shared by the
79	// file readers: it normalizes the records, rejects empty names, duplicate
80	// datasets, and unregistered upstreams, then rejects cycles. The returned
81	// adjacency is the canonical form of the graph's semantics.
82	func validateGraphStructureFromFile(datasets []GraphDataset) (adjacency, error) {
83		adj, err := normalizeDatasets(datasets)
84		if err != nil {
85			return nil, err
86		}
87		if err := validateAdjacencyReferences(adj); err != nil {
88			return nil, err
89		}
90		if err := validateAcyclic(adj); err != nil {
91			return nil, err
92		}
93		return adj, nil
94	}
95	
96	// validateAcyclic reports an error if the parent adjacency contains a cycle
97	// (including a dataset that depends on itself). The error message names the
98	// datasets involved.
99	func validateAcyclic(adj adjacency) error {
100		const (
101			white = 0
102			gray  = 1
103			black = 2
104		)
105		color := make(map[string]int, len(adj))
106		var stack []string
107	
108		var dfs func(node string) error
109		dfs = func(node string) error {
110			color[node] = gray
111			stack = append(stack, node)
112			for _, parent := range adj[node] {
113				switch color[parent] {
114				case gray:
115					// parent is an ancestor of node in the current DFS path, so
116					// following parent edges from parent leads back to parent.
117					idx := 0
118					for stack[idx] != parent {
119						idx++
120					}
121					cycle := make([]string, 0, len(stack)-idx+1)
122					cycle = append(cycle, stack[idx:]...)
123					cycle = append(cycle, parent)
124					return fmt.Errorf("%w: dependency cycle %s", ErrCycle, strings.Join(cycle, " -> "))
125				case white:
126					if err := dfs(parent); err != nil {
127						return err
128					}
129				}
130			}
131			color[node] = black
132			stack = stack[:len(stack)-1]
133			return nil
134		}
135	
136		// Iterate over a sorted snapshot so the first reported cycle is stable
137		// across runs regardless of map iteration order.
138		names := make([]string, 0, len(adj))
139		for name := range adj {
140			names = append(names, name)
141		}
142		sort.Strings(names)
143		for _, name := range names {
144			if color[name] == white {
145				if err := dfs(name); err != nil {
146					return err
147				}
148			}
149		}
150		return nil
151	}
152	
153	// lineageFromAdjacency rebuilds the in-memory graph from validated, normalized
154	// parent adjacency: children are derived from the parent edges, so every
155	// parent/child pair corresponds and both lists stay sorted and duplicate-free.
156	// The result is independent of the caller's record slices.
157	func lineageFromAdjacency(adj adjacency) map[string]*Lineage {
158		graph := make(map[string]*Lineage, len(adj))
159		for name, parents := range adj {
160			graph[name] = &Lineage{
161				Dataset: name,
162				Parents: append([]string(nil), parents...),
163			}
164		}
165		for name, parents := range adj {
166			for _, parent := range parents {
167				graph[parent].Children = append(graph[parent].Children, name)
168			}
169		}
170		for name := range graph {
171			graph[name].Children = uniqueSorted(graph[name].Children)
172		}
173		return graph
174	}
